'use strict';
const $ = id => document.getElementById(id);
const star = (lit=false) => `<svg viewBox="0 0 180 170" aria-hidden="true"><circle cx="90" cy="87" r="69" fill="${lit?'#ffe69a':'#f7e6a7'}" opacity=".55"/><path d="M90 15l21 43 47 7-34 34 8 48-42-23-42 23 8-48-34-34 47-7z" fill="${lit?'#ffdb55':'#ffd067'}" stroke="#ad7c2c" stroke-width="3" stroke-linejoin="round"/><path d="M73 79v7m34-7v7" stroke="#66512b" stroke-width="5" stroke-linecap="round"/><path d="M80 99q10 10 20 0" fill="none" stroke="#66512b" stroke-width="3" stroke-linecap="round"/><ellipse cx="62" cy="94" rx="7" ry="4" fill="#f3ad7e"/><ellipse cx="119" cy="94" rx="7" ry="4" fill="#f3ad7e"/><path d="M15 22v14m-7-7h14M155 127v18m-9-9h18" stroke="#c7993e" stroke-width="3" stroke-linecap="round"/></svg>`;
const balloon = (color='#e9929e') => `<svg viewBox="0 0 160 205" aria-hidden="true"><path d="M80 145c-10 18 16 23 3 39-5 6-5 12-1 17" fill="none" stroke="#a9757e" stroke-width="2.5"/><ellipse cx="80" cy="73" rx="51" ry="64" fill="${color}" stroke="#995d70" stroke-width="2.5"/><path d="M73 137l-4 12h22l-4-12" fill="${color}" stroke="#995d70" stroke-width="2.5" stroke-linejoin="round"/><path d="M51 37q-12 18-10 34" fill="none" stroke="#fff" opacity=".65" stroke-width="8" stroke-linecap="round"/><path d="M63 77v5m34-5v5" stroke="#754d58" stroke-width="4" stroke-linecap="round"/><path d="M71 94q9 9 18 0" stroke="#754d58" stroke-width="2.5" fill="none" stroke-linecap="round"/></svg>`;
const rabbit = (fed=false) => `<svg viewBox="0 0 220 230" aria-hidden="true"><ellipse cx="110" cy="211" rx="71" ry="9" fill="#7da68a" opacity=".17"/><ellipse cx="110" cy="164" rx="52" ry="47" fill="#fffaf0" stroke="#6c8e7a" stroke-width="3"/><ellipse cx="78" cy="65" rx="20" ry="54" transform="rotate(-13 78 65)" fill="#fffaf0" stroke="#6c8e7a" stroke-width="3"/><ellipse cx="140" cy="62" rx="20" ry="53" transform="rotate(12 140 62)" fill="#fffaf0" stroke="#6c8e7a" stroke-width="3"/><ellipse cx="78" cy="61" rx="9" ry="36" transform="rotate(-13 78 61)" fill="#edbdb9"/><ellipse cx="140" cy="59" rx="9" ry="35" transform="rotate(12 140 59)" fill="#edbdb9"/><ellipse cx="110" cy="117" rx="62" ry="51" fill="#fffaf0" stroke="#6c8e7a" stroke-width="3"/><path d="${fed?'M82 113q6-10 12 0m33 0q6-10 12 0':'M87 108v8m45-8v8'}" stroke="#3c574b" stroke-width="5" fill="none" stroke-linecap="round"/><path d="M103 124q7-6 14 0l-7 7z" fill="#d68b91"/><path d="M110 132v5m0 0q-8 7-13 0m13 0q8 7 13 0" fill="none" stroke="#6c8e7a" stroke-width="2.5" stroke-linecap="round"/><ellipse cx="72" cy="126" rx="10" ry="6" fill="#f4c5bd"/><ellipse cx="149" cy="126" rx="10" ry="6" fill="#f4c5bd"/><ellipse cx="78" cy="201" rx="24" ry="12" fill="#fffaf0" stroke="#6c8e7a" stroke-width="3"/><ellipse cx="141" cy="201" rx="24" ry="12" fill="#fffaf0" stroke="#6c8e7a" stroke-width="3"/>${fed?'<path d="M176 55c-20-18-29 8-3 23 26-15 28-36 3-23" fill="#d8848f"/>':''}</svg>`;
const carrot = () => `<svg viewBox="0 0 110 170" aria-hidden="true"><path d="M54 49Q12 39 25 78l22 71q8 18 14 0l25-75q10-35-32-25z" fill="#f1a34f" stroke="#ad7236" stroke-width="3"/><path d="M52 52C27 28 36 9 48 27l10 22c-3-36 18-48 15-18l-9 21c19-28 38-18 16-1l-17 9" fill="#82b67b" stroke="#528663" stroke-width="3" stroke-linejoin="round"/><path d="M28 74l21 7m33 12l-19 6m-26 12l15 6" stroke="#c77e3c" stroke-width="3" stroke-linecap="round"/></svg>`;
$('star-art').innerHTML=star();
$('balloon-art').innerHTML=`<svg viewBox="0 0 290 175"><g transform="translate(25 27) rotate(-15 50 80)">${balloon('#e6a5b4').replace('<svg ','<svg width="110" height="150" ')}</g><g transform="translate(127 5) rotate(12 50 80)">${balloon('#e88e96').replace('<svg ','<svg width="120" height="166" ')}</g><path d="M30 23v12m-6-6h12M259 119v14m-7-7h14" stroke="#c38191" stroke-width="2.5" stroke-linecap="round"/></svg>`;
$('rabbit-art').innerHTML=rabbit();
let settings={difficulty:1,rounds:5,sound:false};
try{const saved=JSON.parse(localStorage.getItem('musaleikir-settings')||'null');if(saved){settings.difficulty=[1,2,3].includes(saved.difficulty)?saved.difficulty:1;settings.rounds=[5,10].includes(saved.rounds)?saved.rounds:5;settings.sound=saved.sound===true;}}catch{}
let current=null,score=0,locked=false,epoch=0,timers=new Set(),drag=null,audioContext=null,selectedFood=false,lastSpot=null;
const field=$('playfield');
const games={stars:{name:'Stjörnurnar',skill:'FÆRA MÚSINA',instruction:'Færðu músina á stjörnuna.',hint:'Þú þarft ekki að smella.',demo:'Færðu bendilinn yfir stjörnuna. Þá kviknar á henni.'},balloons:{name:'Blöðrurnar',skill:'SMELLA',instruction:'Smelltu á blöðruna.',hint:'Einn smellur er nóg.',demo:'Færðu bendilinn á blöðruna og smelltu einu sinni á vinstri músartakkann.'},feeding:{name:'Dýravinir',skill:'DRAGA OG SLEPPA',instruction:'Dragðu gulrótina til kanínunnar.',hint:'Haltu takkanum inni. Dragðu. Slepptu hjá kanínunni.',demo:'Ýttu á gulrótina og haltu músartakkanum inni. Dragðu hana til kanínunnar og slepptu.'}};
function later(fn,ms){const e=epoch;const t=setTimeout(()=>{timers.delete(t);if(e===epoch)fn();},ms);timers.add(t);return t;}
function clearTimers(){epoch++;for(const t of timers)clearTimeout(t);timers.clear();}
function announce(text){$('announcement').textContent=text;}
function updateSound(){ $('sound').textContent=`Hljóð: ${settings.sound?'kveikt':'slökkt'}`;$('sound').setAttribute('aria-pressed',String(settings.sound));$('sound-setting').checked=settings.sound;}
function saveSettings(){try{localStorage.setItem('musaleikir-settings',JSON.stringify(settings));}catch{}updateSound();}
function audioReady(){if(!settings.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});}catch{}}
function chime(){if(!settings.sound||!audioContext)return;try{const t=audioContext.currentTime;[523.25,659.25].forEach((freq,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(0,t+i*.1);gain.gain.linearRampToValueAtTime(.065,t+i*.1+.025);gain.gain.exponentialRampToValueAtTime(.001,t+i*.1+.3);osc.connect(gain);gain.connect(audioContext.destination);osc.start(t+i*.1);osc.stop(t+i*.1+.31);});}catch{}}
function resetDrag(){drag=null;selectedFood=false;}
function closeDialogs(){for(const d of document.querySelectorAll('dialog[open]'))d.close();}
function home(){closeDialogs();clearTimers();resetDrag();current=null;field.replaceChildren();$('menu').hidden=false;$('game').hidden=true;$('home').focus({preventScroll:true});}
function updateProgress(){ $('progress-label').textContent=`${score} af ${settings.rounds}`;$('progress').innerHTML=Array.from({length:settings.rounds},(_,i)=>`<i class="${i<score?'done':''}"></i>`).join('');}
function start(kind){closeDialogs();clearTimers();resetDrag();current=kind;score=0;locked=false;lastSpot=null;$('menu').hidden=true;$('game').hidden=false;field.dataset.game=kind;const g=games[kind];$('game-name').textContent=g.name;$('skill-label').textContent=g.skill;$('instruction').textContent=g.instruction;$('game-hint').textContent=g.hint;updateProgress();renderRound();announce(g.instruction);audioReady();}
function renderRound(){if(!current)return;locked=false;resetDrag();field.replaceChildren();if(current==='feeding'){renderFeeding();return;}const size=[0,160,125,95][settings.difficulty];const w=field.clientWidth,h=field.clientHeight;let pos;if(settings.difficulty===1&&score===0)pos={x:w*.5,y:h*.5};else{const inset=Math.min(size*.6+10,w*.3);const spots=[{x:inset,y:inset},{x:w-inset,y:inset},{x:w*.5,y:h*.5},{x:inset,y:h-inset},{x:w-inset,y:h-inset}];const available=spots.filter(p=>!lastSpot||Math.hypot(p.x-lastSpot.x,p.y-lastSpot.y)>70);pos=available[Math.floor(Math.random()*available.length)]||spots[2];}lastSpot=pos;const target=document.createElement('button');target.type='button';target.className=`target ${current==='stars'?'star-target':'balloon-target'}`;target.setAttribute('aria-label',current==='stars'?'Stjarna':'Blaðra');target.style.cssText=`width:${size}px;height:${current==='stars'?size:size*1.22}px;left:${pos.x}px;top:${pos.y}px`;target.innerHTML=current==='stars'?star():balloon(['#e9929e','#9bbdd5','#b6b0da','#efbc75'][score%4]);field.append(target);if(current==='stars'){let hoverTimer;target.addEventListener('pointerenter',e=>{if(e.pointerType==='touch')return;hoverTimer=later(()=>winTarget(target),180);});target.addEventListener('pointerleave',()=>{clearTimeout(hoverTimer);timers.delete(hoverTimer);});target.addEventListener('click',()=>winTarget(target));}else target.addEventListener('click',()=>winTarget(target));}
function winTarget(target){if(locked||!current||document.querySelector('dialog[open]'))return;locked=true;target.classList.add(current==='stars'?'lit':'popped');if(current==='stars')target.innerHTML=star(true);complete();}
function complete(){score++;updateProgress();chime();announce(`${score} af ${settings.rounds}. Vel gert!`);if(current==='feeding'){const zone=$('feed-zone');zone.classList.add('fed');zone.innerHTML=rabbit(true)+'<span>Takk fyrir!</span>';$('food').style.visibility='hidden';}later(()=>{if(score>=settings.rounds){$('win-text').textContent=current==='stars'?`Þú kveiktir á ${score} stjörnum.`:current==='balloons'?`Þú poppaðir ${score} blöðrur.`:`Þú gafst kanínunni ${score} gulrætur.`;$('win-dialog').showModal();}else renderRound();},current==='feeding'?1050:650);}
function renderFeeding(){const foodSize=[0,130,105,85][settings.difficulty];field.innerHTML=`<div class="food-tray" aria-hidden="true"></div><div class="trail" aria-hidden="true"></div><button class="feed-zone" id="feed-zone" aria-label="Kanína. Slepptu gulrótinni hér.">${rabbit()}<span>Hér er kanínan</span></button><button class="food" id="food" aria-label="Gulrót. Haltu inni og dragðu til kanínunnar." style="width:${foodSize}px;height:${foodSize*1.35}px">${carrot()}</button>`;const food=$('food'),zone=$('feed-zone');food.addEventListener('pointerdown',e=>{if(locked||document.querySelector('dialog[open]')||e.button!==0)return;e.preventDefault();audioReady();const fr=field.getBoundingClientRect(),r=food.getBoundingClientRect();drag={id:e.pointerId,startX:e.clientX,startY:e.clientY,offsetX:e.clientX-r.left-r.width/2,offsetY:e.clientY-r.top-r.height/2,originX:r.left+r.width/2-fr.left,originY:r.top+r.height/2-fr.top};food.setPointerCapture(e.pointerId);food.classList.add('dragging');});food.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const r=field.getBoundingClientRect();food.style.left=`${Math.max(20,Math.min(r.width-20,e.clientX-r.left-drag.offsetX))}px`;food.style.top=`${Math.max(20,Math.min(r.height-20,e.clientY-r.top-drag.offsetY))}px`;zone.classList.toggle('ready',isInZone(e.clientX,e.clientY));});food.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const moved=Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>8;const success=isInZone(e.clientX,e.clientY);cancelDrag();if(success){feed();}else if(moved){announce('Prófaðu aftur. Dragðu gulrótina til kanínunnar.');}});food.addEventListener('pointercancel',cancelDrag);food.addEventListener('lostpointercapture',()=>{if(drag)cancelDrag();});food.addEventListener('click',e=>{if(e.detail!==0||locked)return;selectedFood=true;food.classList.add('selected');zone.classList.add('ready');announce('Gulrót valin. Veldu kanínuna.');zone.focus();});zone.addEventListener('click',()=>{if(selectedFood)feed();});}
function isInZone(x,y){const r=$('feed-zone').getBoundingClientRect();const margin=settings.difficulty===1?26:settings.difficulty===2?16:5;const food=$('food').getBoundingClientRect();const overlap=food.right>r.left&&food.left<r.right&&food.bottom>r.top&&food.top<r.bottom;return (x>r.left-margin&&x<r.right+margin&&y>r.top-margin&&y<r.bottom+margin)||overlap;}
function cancelDrag(){if(!drag)return;const food=$('food');drag=null;if(food){food.classList.remove('dragging');food.style.left='22%';food.style.top='50%';}$('feed-zone')?.classList.remove('ready');}
function feed(){if(locked||!current)return;locked=true;resetDrag();complete();}
function demo(){if(!current)return;cancelDrag();const kind=current,g=games[kind];$('demo-title').textContent=g.instruction;$('demo-text').textContent=g.demo;$('demo-stage').dataset.kind=kind;$('demo-stage').innerHTML=`<div class="demo-target">${kind==='stars'?star():kind==='balloons'?balloon():rabbit()}</div>${kind==='feeding'?`<div class="demo-food">${carrot()}</div>`:''}<div class="demo-cursor">☝</div>`;$('demo-dialog').showModal();}
document.querySelectorAll('[data-game]').forEach(b=>b.addEventListener('click',()=>start(b.dataset.game)));
$('home').addEventListener('click',home);$('back').addEventListener('click',home);$('restart').addEventListener('click',()=>start(current));$('again').addEventListener('click',()=>start(current));$('win-home').addEventListener('click',home);$('demo-button').addEventListener('click',demo);$('demo-done').addEventListener('click',()=>{$('demo-dialog').close();audioReady();});
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));
$('sound').addEventListener('click',()=>{settings.sound=!settings.sound;saveSettings();audioReady();if(settings.sound)chime();});
$('settings').addEventListener('click',()=>{cancelDrag();$('difficulty').value=settings.difficulty;$('rounds').value=settings.rounds;$('sound-setting').checked=settings.sound;$('settings-dialog').showModal();});
$('settings-form').addEventListener('submit',e=>{e.preventDefault();const changed=settings.difficulty!==Number($('difficulty').value)||settings.rounds!==Number($('rounds').value);settings={difficulty:Number($('difficulty').value),rounds:Number($('rounds').value),sound:$('sound-setting').checked};saveSettings();audioReady();$('settings-dialog').close();if(current&&changed)start(current);});
$('win-dialog').addEventListener('cancel',e=>{e.preventDefault();home();});
window.addEventListener('blur',cancelDrag);
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(current&&!locked){clearTimers();renderRound();}},160);});
updateSound();
